{
  "steps": [
    {
      "step_id": "cb_step_1",
      "title": "Select the CT volume",
      "simple": "Choose the CT scan of the injured long bone to use for planning.",
      "detailed": "This CT volume is the foundation for all segmentation and 3D reconstruction, so choose the scan that best shows the fractured bone and surrounding anatomy. Correct selection ensures the downstream steps work on the right imaging data."
    },
    {
      "step_id": "cb_step_2",
      "title": "Decide whether to crop the volume",
      "simple": "Choose Yes to crop the CT to a smaller region around the fracture, or No to keep the full volume.",
      "detailed": "Cropping focuses processing on the area around the fracture, which can make segmentation faster and less cluttered by unrelated anatomy. If you choose No, you will skip the cropping steps and move directly to segmenting the bone."
    },
    {
      "step_id": "cb_step_3",
      "title": "Create a region of interest",
      "simple": "In the Markups module, click ROI to create an empty region box called Longbone_Region.",
      "detailed": "This box will define the area of the CT volume kept during cropping. Creating it now lets you draw a tight boundary around the fractured bone in the next step and helps exclude irrelevant tissue from later processing."
    },
    {
      "step_id": "cb_step_4",
      "title": "Draw the ROI around the fracture",
      "simple": "Click and drag in the slice views to draw the box tightly around the fractured long bone region.",
      "detailed": "This region should enclose the whole fracture zone plus enough bone on each side for later registration. Including all relevant bone while excluding surrounding soft tissue makes the cropped volume cleaner and improves the quality of segmentation."
    },
    {
      "step_id": "cb_step_5",
      "title": "Confirm the drawn ROI",
      "simple": "Select the Longbone_Region ROI you drew.",
      "detailed": "This confirms which region of interest will be used for cropping. Verify that it is the box you just placed, because the crop will be based on exactly this boundary."
    },
    {
      "step_id": "cb_step_6",
      "title": "Crop the CT volume",
      "simple": "Click the Confirm crop button.",
      "detailed": "This applies the ROI to the CT volume and produces a focused working volume around the fracture. The cropped volume is used for all subsequent segmentation and planning, so a clean, well-centered crop improves workflow speed and accuracy."
    },
    {
      "step_id": "cb_step_7",
      "title": "Create the reference segmentation",
      "simple": "In the Segment Editor module, create a new segmentation named Reference_Segmentation.",
      "detailed": "This segmentation will hold the bone fragment that will be treated as the fixed or reference side of the fracture. Keeping it separate from the moving fragment makes it possible to plan the reduction by aligning the displaced piece back to this stable reference."
    },
    {
      "step_id": "cb_step_8",
      "title": "Add and name the reference segment",
      "simple": "Click Add, rename the segment to Reference_Segment, and set its color to Sage Green.",
      "detailed": "This segment will contain the actual bone pixels belonging to the reference fragment. The distinct sage green color lets you easily tell the fixed side apart from the moving fragment in later steps."
    },
    {
      "step_id": "cb_step_9",
      "title": "Open the Threshold tool",
      "simple": "In the Segment Editor module, click Threshold.",
      "detailed": "Thresholding selects bone based on CT density, which is higher than surrounding soft tissue. Opening the tool prepares you to set a range that captures the bone of the reference fragment without including other tissues."
    },
    {
      "step_id": "cb_step_10",
      "title": "Set the threshold range for the reference fragment",
      "simple": "Adjust the threshold slider until the highlighted region covers the bone of the reference fragment.",
      "detailed": "A threshold that is too low includes soft tissue and noise, while one that is too high misses parts of the bone. Choose a range that isolates the cortical and trabecular bone of the reference fragment, because this directly determines the quality of the initial segment."
    },
    {
      "step_id": "cb_step_11",
      "title": "Apply the reference threshold",
      "simple": "In the Segment Editor module, click Apply.",
      "detailed": "Applying the threshold creates an initial bone segment for the reference fragment. The result may still contain small stray pieces, which will be cleaned up in the next Islands step."
    },
    {
      "step_id": "cb_step_12",
      "title": "Open the Islands tool",
      "simple": "In the Segment Editor module, click Islands.",
      "detailed": "Thresholding often produces many disconnected bone pieces, called islands. The Islands tool lets you keep only the piece that belongs to the reference fragment and remove unrelated fragments in the same slice."
    },
    {
      "step_id": "cb_step_13",
      "title": "Choose Keep Selected Island",
      "simple": "Select the Keep selected island option.",
      "detailed": "This option tells the editor to preserve only the bone island you click on next and remove all other islands. It is the key step for isolating the reference fragment from the rest of the thresholded bone."
    },
    {
      "step_id": "cb_step_14",
      "title": "Click the reference fragment",
      "simple": "Click on the reference bone fragment in a slice view to keep it.",
      "detailed": "The Keep selected island effect will remove every island except the one you click. Click on the fragment that should remain fixed during reduction, so the reference segment accurately represents that side of the fracture."
    },
    {
      "step_id": "cb_step_15",
      "title": "Create the moving segmentation",
      "simple": "In the Segment Editor module, create a new segmentation named Moving_Segmentation.",
      "detailed": "This segmentation will contain the displaced bone fragment that must be moved back into alignment during reduction. Keeping it separate from the reference segmentation lets the software treat the two fragments independently during registration and planning."
    },
    {
      "step_id": "cb_step_16",
      "title": "Add and name the moving segment",
      "simple": "Click Add, rename the segment to Moving_Segment, and set its color to Cyan.",
      "detailed": "This segment holds the bone pixels of the displaced or moving fragment. The cyan color makes it easy to distinguish from the sage green reference fragment when evaluating the fracture alignment."
    },
    {
      "step_id": "cb_step_17",
      "title": "Open the Threshold tool",
      "simple": "In the Segment Editor module, click Threshold.",
      "detailed": "Thresholding will now select the bone of the moving fragment based on CT density. The tool is opened so you can set the correct range for this fragment, just as you did for the reference side."
    },
    {
      "step_id": "cb_step_18",
      "title": "Set the threshold range for the moving fragment",
      "simple": "Adjust the threshold slider; the default matches the reference threshold and should work for most cases.",
      "detailed": "The bone density of the moving fragment is usually similar to the reference fragment, so the default range is often appropriate. If the fragment is more fragmented or affected by artifact, adjust the range to include all of its bone while excluding soft tissue."
    },
    {
      "step_id": "cb_step_19",
      "title": "Apply the moving threshold",
      "simple": "In the Segment Editor module, click Apply.",
      "detailed": "Applying the threshold creates the initial bone segment for the moving fragment. Stray islands will be removed in the next step, leaving only the fragment that must be repositioned."
    },
    {
      "step_id": "cb_step_20",
      "title": "Open the Islands tool",
      "simple": "In the Segment Editor module, click Islands.",
      "detailed": "Just as with the reference side, thresholding may create multiple disconnected bone islands. The Islands tool lets you isolate the moving fragment and remove unrelated pieces."
    },
    {
      "step_id": "cb_step_21",
      "title": "Choose Keep Selected Island",
      "simple": "Select the Keep selected island option.",
      "detailed": "This option makes the editor keep only the bone island you click next. It is the step that isolates the moving fragment from the rest of the thresholded bone."
    },
    {
      "step_id": "cb_step_22",
      "title": "Click the moving fragment",
      "simple": "Click on the displaced bone fragment in a slice view to keep it.",
      "detailed": "The Keep selected island effect will preserve only the island you click on. Choose the fragment that needs to be moved back into alignment, because this segment defines the moving side for reduction planning."
    },
    {
      "step_id": "cb_step_23",
      "title": "Select the reference segmentation",
      "simple": "Select the reference segmentation in the Reference segmentation (fixed) section.",
      "detailed": "This tells the software which segmentation is the fixed or target side of the fracture. The moving fragment will later be aligned back to this reference, so choosing the correct one is essential for a proper reduction plan."
    },
    {
      "step_id": "cb_step_24",
      "title": "Reconstruct the reference fragment in 3D",
      "simple": "Click the 3D Reconstruction (reference) button.",
      "detailed": "This creates a 3D surface model of the fixed reference fragment. The 3D model is needed to visualize the fracture, detect matching fracture surfaces, and plan how the moving fragment should be brought back into alignment."
    },
    {
      "step_id": "cb_step_25",
      "title": "Select the moving segmentation",
      "simple": "Select the moving segmentation in the Moving segmentation (repositioned) section.",
      "detailed": "This identifies which segmentation contains the fragment that will be repositioned. Selecting the right moving segmentation ensures that the reconstruction and registration act on the correct displaced fragment."
    },
    {
      "step_id": "cb_step_26",
      "title": "Reconstruct the moving fragment in 3D",
      "simple": "Click the 3D Reconstruction (moving) button.",
      "detailed": "This creates a 3D surface model of the displaced moving fragment. Together with the reference model, it allows the software to analyze the fracture surfaces and calculate how the moving fragment must be realigned."
    },
    {
      "step_id": "cb_step_27",
      "title": "Detect fracture surfaces",
      "simple": "Click the Detect fracture surfaces button.",
      "detailed": "This identifies the irregular mating surfaces on both fracture fragments. These surfaces are used to match the moving fragment to the reference fragment and are essential for computing a realistic reduction alignment."
    },
    {
      "step_id": "cb_step_28",
      "title": "Initialize registration",
      "simple": "Click the Initialize registration button.",
      "detailed": "This creates an initial alignment between the moving and reference fragments based on the detected fracture surfaces. A good starting alignment makes any later manual refinement quicker and helps produce a more accurate reduction plan."
    },
    {
      "step_id": "cb_step_29",
      "title": "Adjust the 3D view",
      "simple": "Rotate, zoom, and pan the 3D view until you have a clear view of both bone fragments.",
      "detailed": "Reposition the camera to inspect the fracture from multiple angles. This helps you assess the current alignment between the reference and moving fragments before the reduction plan is generated. This step only changes your viewing perspective, so no clicking or placement is needed."
    },
    {
      "step_id": "cb_step_30",
      "title": "Plan the reduction",
      "simple": "Click the Reduction planning button.",
      "detailed": "This uses the detected fracture surfaces and the initial registration to compute a reduction plan that aligns the moving fragment back onto the reference fragment. Review the result to confirm it restores the anatomical position of the fractured bone, since this plan guides the final reduction."
    }
  ]
}
